type Entities=Map<bigint,SqliteRow>;
async function entities(rows:readonly SqliteRow[],count:number,floats:readonly Ieee754Column[],o:ArtifactSqliteOptions):Promise<Entities>{const result:Entities=new Map();for(let n=0;n<rows.length;n++){await checkpoint(o,n,rows.length);const r=rows[n]!;if(r.rowid<=0n||r.values.length!==count+floats.length*2||artifactSqliteInteger(r,0)!==r.rowid||result.has(r.rowid))throw Error("EN1993 identity or column shape differs");for(const f of floats)readBinary64(r,f.index,floats);result.set(r.rowid,r)}return result}
